contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        for(uint i=0;i<_tos.length;i++){
            vm.assume(_tos[i] != address(0));
            vm.assume(_tos[i] != address(this));
            vm.assume(_tos[i] != address(c));
        }
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        vm.assume(from != address(this));
        vm.assume(from != address(c));
        bool success;
        bytes memory ret;
        (success, ret) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256)", from, caddress, _tos, v));
        bool expected = true;
        assertTrue(success ? (abi.decode(ret, (bool)) == expected) : true);
    }
